mapper.select:
SELECT * FROM wms_inbound where bool_delete_enum = 0
and inbound_way = #{inboundWay}
and quality_testing_enum & #{qualityTestingEnum} > 0
and review_status = #{reviewStatus}
and basic_class & #{ basicClass} > 0
and serial_number like CONCAT('%', #{serialNumber},'%')
and shipment_number like CONCAT('%', #{shipmentNumber},'%')
and license_plate like CONCAT('%', #{licensePlate},'%')
and create_time > #{createTime[0]}
and create_time < #{createTime[1]}
and purchase_SN like CONCAT('%', #{purchaseSN},'%')
and bool_party_a = 1
and bool_party_a = 0
and supplier_id = #{supplierId}
and (editor_name like CONCAT('%', #{operatorName},'%') or reviewer_name like CONCAT('%', #{operatorName},'%') or applicant_name like CONCAT('%', #{operatorName},'%'))
and project_ids is null
and project_ids is not null
and find_in_set(#{projectId},project_ids)
and reject_status in
#{item}

select
IFNULL(sum(wid.amount), 0)
from wms_inbound as wi,
wms_inbound_detail as wid
where wi.bool_delete_enum = 0
and wid.bool_delete_enum = 0
and wi.id = wid.inbound_id

    and wi.purchase_id = #{purchaseOrderId}


    and wi.review_status = #{reviewStatus}

select wi.* from wms_inbound wi left join scm_purchase_order spo on wi.purchase_id = spo.id left join wms_inbound_detail wid on wi.id = wid.inbound_id where wi.bool_delete_enum = 0 and wi.review_status = 2
and wi.reject_status = #{rejectStatus}
and wi.inbound_way = #{inboundWay}
and spo.branch_company_id = #{branchCompanyId}
and wi.basic_class & #{ basicClass} > 0
and wi.serial_number like CONCAT('%', #{serialNumber},'%')
and wi.shipment_number like CONCAT('%', #{shipmentNumber},'%')
and wi.license_plate like CONCAT('%', #{licensePlate},'%')
and wi.review_time > #{inboundTime[0]}
and wi.review_time < #{inboundTime[1]}
and wi.purchase_SN like CONCAT('%', #{purchaseSN},'%')
and wi.bool_party_a = 1
and wi.bool_party_a = 0
and wi.supplier_id = #{supplierId}
and (wi.editor_name like CONCAT('%', #{operatorName},'%') or wi.applicant_name like CONCAT('%', #{operatorName},'%') or wi.reviewer_name like CONCAT('%', #{operatorName},'%'))
and wi.project_ids is null
and wi.project_ids IS NOT NULL
and find_in_set(#{projectId},wi.project_ids)
and wid.workshop_id in
#{item}
group by wi.id

mapper.update:
UPDATE wms_inbound
SET editable = #{value}
WHERE original_id = #{id}
  and bool_delete_enum = 0

mapper.select:
SELECT IFNULL(SUM(amount), 0)
FROM wms_inbound
WHERE bool_delete_enum = 0
AND review_status = 2

    AND purchase_id =#{purchaseId}


    AND supplier_id =#{supplierId}

SELECT IFNULL(SUM(amount_no_freight), 0)
FROM wms_inbound
WHERE bool_delete_enum = 0
AND review_status = 2

    AND purchase_id =#{purchaseId}


    AND supplier_id =#{supplierId}

SELECT wms_inbound_detail.id, wms_inbound.id inboundId, wms_inbound_detail.create_time, wms_inbound.applicant_name, wms_inbound_detail.thickness, wms_inbound_detail.specification, wms_inbound_detail.area, wms_inbound_detail.create_time, wms_inbound_detail.workshop_id, wms_inbound_detail.nest_surplus_code, wms_inbound_detail.classify_id, wms_inbound_detail.classify_name, wms_inbound_detail.mete, wms_inbound.review_status, wms_inbound_detail.dxf_url, wms_inbound_detail.img_url FROM wms_inbound_detail wms_inbound_detail LEFT JOIN wms_inbound wms_inbound ON wms_inbound_detail.inbound_id = wms_inbound.id WHERE wms_inbound_detail.bool_delete_enum = 0
AND wms_inbound_detail.bool_nest_surplus =#{boolNestSurplus}
AND wms_inbound.review_status = #{reviewStatus}
